    PREV_FAILURE_TIMES = #{prevFailureTimes,jdbcType=INTEGER},            PASSWORD = #{password,jdbcType=VARCHAR},            CHANGE_IND = #{changeInd,jdbcType=VARCHAR},            PASSWORD_STATUS = #{passwordStatus,jdbcType=VARCHAR},            LAST_UPD_TIMESTAMP = #{lastUpdTimestamp,jdbcType=VARCHAR},            PASSWORD_EFFECT_DATE = #{passwordEffectDate,jdbcType=TIMESTAMP},            CREATE_TIMESTAMP = #{createTimestamp,jdbcType=VARCHAR},            DAY_FAILURE_TIMES = #{dayFailureTimes,jdbcType=INTEGER},            FAILURE_TIMES = #{failureTimes,jdbcType=INTEGER}        where INTERNAL_KEY = #{internalKey,jdbcType=INTEGER}
